import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Handl Single-File Component (.hfc) Format — design detail","description":"","frontmatter":{"title":"Handl Single-File Component (`.hfc`) Format — design detail","type":"design","date":"2026-10-28T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","refs":["ADR-0116"]},"headers":[],"relativePath":"web/project/design/0116-handl-sfc-format.md","filePath":"vendored/web/project/design/0116-handl-sfc-format.md"}'),a={name:`web/project/design/0116-handl-sfc-format.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-single-file-component-hfc-format-—-design-detail" tabindex="-1">Handl Single-File Component (<code>.hfc</code>) Format — design detail <a class="header-anchor" href="#handl-single-file-component-hfc-format-—-design-detail" aria-label="Permalink to “Handl Single-File Component (.hfc) Format — design detail”">​</a></h1><p>Moved verbatim from ADR-0116 (ADR-0161 size budget). The ADR carries the rules; this page carries the context, tables, phases and trade-offs.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./0094-generic-ast-transform-engine.html">ADR-0094 — Generic AST Transform Engine</a> makes transforms first-class <code>Ast → Ast</code> passes. <a href="./0114-handl-compile-plugin-architecture.html">ADR-0114 — Handl Compile Plugin</a> is planned to lower Handl to JavaScript. <a href="./0115-handl-sdkgen-dts-js.html">ADR-0115 — <code>.d.ts</code> SDKgen</a> will generate Handl port/adapter pairs from NPM package declarations. <a href="./0117-handl-view-component-syntax.html">ADR-0117 — Handl View / JSX-like Component Syntax</a> defines the inline <code>view</code> syntax itself. The missing piece is a file format that bundles the view, the script, and the style into one source file, the way Vue SFCs do.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Add an <code>.hfc</code> (Handl File Component) file format and loader.</p><h3 id="file-layout" tabindex="-1">File layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to “File layout”">​</a></h3><p>An <code>.hfc</code> file has three optional regions:</p><div class="language-hfc"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hfc</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;script&gt;</span></span>
<span class="line"><span>export props := #{ name: String, greet?: Bool }</span></span>
<span class="line"><span>state counter := 0</span></span>
<span class="line"><span>export bump := () ~&gt; counter := counter + 1</span></span>
<span class="line"><span>&lt;/script&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;template&gt;</span></span>
<span class="line"><span>  &lt;div class=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>    &lt;h1 v-if=&quot;greet&quot;&gt;Hello, {name}&lt;/h1&gt;</span></span>
<span class="line"><span>    &lt;h1 v-else&gt;Hey, {name}&lt;/h1&gt;</span></span>
<span class="line"><span>    &lt;button @click=&quot;bump&quot;&gt;{counter}&lt;/button&gt;</span></span>
<span class="line"><span>    &lt;slot name=&quot;footer&quot;&gt;Default footer&lt;/slot&gt;</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>&lt;/template&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;style scoped&gt;</span></span>
<span class="line"><span>.hello { color: blue; }</span></span>
<span class="line"><span>&lt;/style&gt;</span></span></code></pre></div><h3 id="loader-behavior" tabindex="-1">Loader behavior <a class="header-anchor" href="#loader-behavior" aria-label="Permalink to “Loader behavior”">​</a></h3><ol><li>Splits the file at region markers (<code>&lt;script&gt;</code>, <code>&lt;template&gt;</code>, <code>&lt;style&gt;</code>).</li><li>Parses <code>&lt;script&gt;</code> and <code>&lt;script setup&gt;</code> as a Handl module.</li><li>Parses <code>&lt;template&gt;</code> as a <code>view</code> block and runs the <code>component</code> transform from ADR-0117.</li><li>Carries <code>&lt;style&gt;</code> as data, rewriting selectors if <code>scoped</code> is present and adding the generated scope id to every host element in the <code>&lt;template&gt;</code>.</li><li>Emits a single Handl module plus a CSS string/artifact for the compile-to-JS backend.</li></ol><h3 id="script-variants" tabindex="-1"><code>&lt;script&gt;</code> variants <a class="header-anchor" href="#script-variants" aria-label="Permalink to “&lt;script&gt; variants”">​</a></h3><ul><li><code>&lt;script&gt;</code>: ordinary module. <code>export</code>ed names are the public API and are available in the template. <code>state</code> declarations become reactive state. <code>props</code> (when exported as a record) becomes the component&#39;s props type.</li><li><code>&lt;script setup&gt;</code> (Vue-style): the entire region is a setup function. Top-level values and arrows are automatically exposed to the template and returned by the setup. This is the default for one-component-per-file files.</li></ul><h3 id="scoped-styles" tabindex="-1">Scoped styles <a class="header-anchor" href="#scoped-styles" aria-label="Permalink to “Scoped styles”">​</a></h3><p>When <code>&lt;style scoped&gt;</code> is present, the loader:</p><ol><li>Generates a unique scope id for the file.</li><li>Rewrites CSS selectors to include the scope attribute (e.g. <code>.hello[data-v-1a2b3c]</code>).</li><li>Adds the scope id to every host element in the <code>&lt;template&gt;</code>.</li><li>Emits the processed CSS as a string that the compile-to-JS backend writes to a <code>&lt;style&gt;</code> block or a <code>.css</code> asset.</li></ol><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to “Slots”">​</a></h3><p>Slots are explicit <code>&lt;slot&gt;</code> elements. A default slot has no <code>name</code>; named slots use <code>name=&quot;...&quot;</code>. Scoped slots pass data back to the parent through a <code>let:</code> attribute on the slot and an <code>each</code> attribute for iteration. The lowering is the same Handl callback arrow mechanism described in ADR-0117.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>One file per component, matching Vue/Astro/Svelte conventions.</li><li>The loader is a small pre-processor; the real syntax work is in ADR-0117.</li><li>The style step is not typechecked by Handl; it is emitted as data for the JS target.</li><li>Astro/Svelte/Vue/React can share the same <code>&lt;template&gt;</code> syntax and just need a different <code>target</code> config in the compile step.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./0094-generic-ast-transform-engine.html">ADR-0094 — Generic AST Transform Engine</a></li><li><a href="./0114-handl-compile-plugin-architecture.html">ADR-0114 — Handl Compile Plugin</a></li><li><a href="./0115-handl-sdkgen-dts-js.html">ADR-0115 — Handl SDK Generator: TypeScript Declaration Backend</a></li><li><a href="./0117-handl-view-component-syntax.html">ADR-0117 — Handl View / JSX-like Component Syntax</a></li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};